import{_ as t,o,c as r,ag as n}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Going Live: Stripe Keys & Webhooks (Test vs Live)","description":"","frontmatter":{},"headers":[],"relativePath":"STRIPE_GOING_LIVE_RENDER.md","filePath":"STRIPE_GOING_LIVE_RENDER.md"}'),s={name:"STRIPE_GOING_LIVE_RENDER.md"};function i(d,e,a,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="going-live-stripe-keys-webhooks-test-vs-live" tabindex="-1">Going Live: Stripe Keys &amp; Webhooks (Test vs Live) <a class="header-anchor" href="#going-live-stripe-keys-webhooks-test-vs-live" aria-label="Permalink to &quot;Going Live: Stripe Keys &amp; Webhooks (Test vs Live)&quot;">​</a></h1><p>When you deploy your project to <strong>Render</strong> (or any live host), you <strong>must not</strong> use the same Stripe setup as localhost. Here’s what works where and what to change.</p><hr><h2 id="_1a-testing-on-render-with-test-credentials-no-real-payments" tabindex="-1">1a. Testing on Render with test credentials (no real payments) <a class="header-anchor" href="#_1a-testing-on-render-with-test-credentials-no-real-payments" aria-label="Permalink to &quot;1a. Testing on Render with test credentials (no real payments)&quot;">​</a></h2><p>You can deploy to Render and still use <strong>test</strong> keys so that only test cards work and no real money is charged. The only thing that won’t work is the <strong>Stripe CLI webhook secret</strong> — that secret is only for <code>stripe listen</code> forwarding to localhost. For Render you need a webhook that Stripe sends to your <strong>live URL</strong>.</p><p><strong>Do this:</strong></p><ol><li><p><strong>Use test keys on Render</strong></p><ul><li>Backend: <code>STRIPE_SECRET_KEY</code> = <code>sk_test_...</code></li><li>Frontend: <code>VITE_STRIPE_PUBLISHABLE_KEY</code> = <code>pk_test_...</code></li><li><code>FRONTEND_URL</code> = your Render frontend URL (e.g. <code>https://your-app.onrender.com</code>)</li></ul></li><li><p><strong>Create a test-mode webhook endpoint in Stripe Dashboard (for your Render URL)</strong></p><ul><li>Open <a href="https://dashboard.stripe.com" target="_blank" rel="noreferrer">Stripe Dashboard</a>.</li><li><strong>Turn on “Test mode”</strong> (toggle top right).</li><li>Go to <strong>Developers → Webhooks</strong>.</li><li>Click <strong>Add endpoint</strong>.</li><li><strong>Endpoint URL:</strong> <code>https://your-backend.onrender.com/webhooks/stripe</code><br> (Use the real URL of your backend on Render.)</li><li><strong>Events to send:</strong> same as production (e.g. <code>checkout.session.completed</code>, <code>payment_intent.succeeded</code>, <code>account.updated</code>, etc.) or “Receive all events”.</li><li>Create the endpoint. Stripe shows a <strong>Signing secret</strong> (<code>whsec_...</code>). Copy it.</li></ul></li><li><p><strong>Set the webhook secret on Render</strong></p><ul><li>In Render, for your <strong>backend</strong> service, set:</li><li><code>STRIPE_WEBHOOK_SECRET</code> = the <code>whsec_...</code> from the <strong>Dashboard</strong> endpoint you just created (not the one from <code>stripe listen</code>).</li></ul></li><li><p><strong>Redeploy</strong> the backend so it uses the new env.</p></li></ol><p>After this, your Render app uses test credentials and test cards (e.g. 4242 4242 4242 4242), and webhooks are signed with the Dashboard endpoint secret so verification succeeds. When you’re ready for real payments, switch to live keys and add a <strong>live</strong> webhook endpoint as in section 4 below.</p><hr><h2 id="_1-test-sandbox-vs-live-–-quick-answer" tabindex="-1">1. Test (sandbox) vs Live – quick answer <a class="header-anchor" href="#_1-test-sandbox-vs-live-–-quick-answer" aria-label="Permalink to &quot;1. Test (sandbox) vs Live – quick answer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Localhost (development)</th><th>Live (e.g. Render)</th></tr></thead><tbody><tr><td><strong>Stripe mode</strong></td><td><strong>Test mode</strong> (sandbox)</td><td><strong>Live mode</strong></td></tr><tr><td><strong>Publishable key</strong></td><td><code>pk_test_...</code></td><td><code>pk_live_...</code></td></tr><tr><td><strong>Secret key</strong></td><td><code>sk_test_...</code></td><td><code>sk_live_...</code></td></tr><tr><td><strong>Webhook secret</strong></td><td>From <strong>Stripe CLI</strong> (<code>stripe listen</code>)</td><td>From <strong>Stripe Dashboard</strong> (webhook endpoint for your live URL)</td></tr><tr><td><strong>Webhook URL</strong></td><td>Stripe CLI forwards to <code>http://localhost:4000/webhooks/stripe</code></td><td>Your live URL, e.g. <code>https://your-api.onrender.com/webhooks/stripe</code></td></tr><tr><td><strong>Real money?</strong></td><td>No – test cards only</td><td>Yes – real charges</td></tr></tbody></table><p><strong>So:</strong></p><ul><li><strong>Test credentials (sandbox)</strong> will “run” on Render (app won’t crash), but they only process <strong>test</strong> payments. No real money. Customers cannot pay with real cards.</li><li>For <strong>live</strong> you must use <strong>live</strong> API keys and a <strong>live</strong> webhook endpoint. The <strong>webhook secret from Stripe CLI will not work</strong> for live; it is only for CLI-forwarded events to localhost.</li></ul><hr><h2 id="_2-what-each-key-secret-is-for" tabindex="-1">2. What each key/secret is for <a class="header-anchor" href="#_2-what-each-key-secret-is-for" aria-label="Permalink to &quot;2. What each key/secret is for&quot;">​</a></h2><h3 id="publishable-key-frontend" tabindex="-1">Publishable key (frontend) <a class="header-anchor" href="#publishable-key-frontend" aria-label="Permalink to &quot;Publishable key (frontend)&quot;">​</a></h3><ul><li><strong>Test:</strong> <code>pk_test_...</code> – from Stripe Dashboard → <strong>Developers → API keys</strong> (with “Test mode” toggled <strong>on</strong>).</li><li><strong>Live:</strong> <code>pk_live_...</code> – same place, with “Test mode” toggled <strong>off</strong>.</li><li><strong>Where used:</strong> Frontend (e.g. <code>VITE_STRIPE_PUBLISHABLE_KEY</code>). Used by Stripe.js / Checkout on the client. No real charges in test mode.</li></ul><h3 id="secret-key-backend" tabindex="-1">Secret key (backend) <a class="header-anchor" href="#secret-key-backend" aria-label="Permalink to &quot;Secret key (backend)&quot;">​</a></h3><ul><li><strong>Test:</strong> <code>sk_test_...</code> – from same API keys page (test mode on). <strong>Never</strong> put this in frontend or public repo.</li><li><strong>Live:</strong> <code>sk_live_...</code> – same page (test mode off).</li><li><strong>Where used:</strong> Backend only (<code>STRIPE_SECRET_KEY</code>). Used for creating Checkout sessions, PaymentIntents, Connect accounts, etc.</li></ul><h3 id="webhook-signing-secret" tabindex="-1">Webhook signing secret <a class="header-anchor" href="#webhook-signing-secret" aria-label="Permalink to &quot;Webhook signing secret&quot;">​</a></h3><ul><li><strong>Localhost:</strong> You run <code>stripe listen --forward-to http://localhost:4000/webhooks/stripe</code>. The CLI gives you a <strong>temporary</strong> secret like <code>whsec_...</code>. You put it in <code>STRIPE_WEBHOOK_SECRET</code>. This secret is <strong>only</strong> for events the CLI forwards to your local server. It <strong>does not</strong> work for events Stripe sends to a live URL.</li><li><strong>Live:</strong> You create a <strong>Webhook endpoint</strong> in Stripe Dashboard (see below) with your <strong>live</strong> URL. Stripe shows a <strong>different</strong> signing secret for that endpoint. You put <strong>that</strong> secret in <code>STRIPE_WEBHOOK_SECRET</code> on Render. The CLI secret must <strong>not</strong> be used in production.</li></ul><hr><h2 id="_3-will-test-sandbox-credentials-run-on-render" tabindex="-1">3. Will test (sandbox) credentials “run” on Render? <a class="header-anchor" href="#_3-will-test-sandbox-credentials-run-on-render" aria-label="Permalink to &quot;3. Will test (sandbox) credentials “run” on Render?&quot;">​</a></h2><p><strong>Yes, they will run</strong> in the sense that:</p><ul><li>The server and frontend will start.</li><li>Stripe API calls will succeed (in test mode).</li><li>Checkout will open; <strong>test cards</strong> (e.g. 4242 4242 4242 4242) will work.</li></ul><p><strong>But:</strong></p><ul><li><strong>No real money</strong> is charged. Real cards will be declined or not accepted depending on how you’ve set things up.</li><li>The <strong>Stripe CLI webhook secret</strong> is only valid for the CLI forwarding to localhost. Once you deploy to Render, Stripe sends webhooks <strong>directly</strong> to your live URL. Those events are signed with the <strong>live endpoint’s</strong> secret. If you keep using the CLI secret on Render, <strong>webhook signature verification will fail</strong> and events (e.g. <code>payment_intent.succeeded</code>, <code>checkout.session.completed</code>) will not be accepted by your app.</li></ul><p>So for a <strong>real</strong> live site where customers pay with real cards:</p><ol><li>Use <strong>live</strong> publishable and secret keys on Render.</li><li>Create a <strong>live</strong> webhook endpoint in Stripe and use <strong>that</strong> endpoint’s signing secret on Render.</li><li>Do <strong>not</strong> use the Stripe CLI webhook secret on Render.</li></ol><hr><h2 id="_4-what-to-do-for-live-on-render" tabindex="-1">4. What to do for live on Render <a class="header-anchor" href="#_4-what-to-do-for-live-on-render" aria-label="Permalink to &quot;4. What to do for live on Render&quot;">​</a></h2><h3 id="step-1-get-live-api-keys" tabindex="-1">Step 1: Get live API keys <a class="header-anchor" href="#step-1-get-live-api-keys" aria-label="Permalink to &quot;Step 1: Get live API keys&quot;">​</a></h3><ol><li>Open <a href="https://dashboard.stripe.com" target="_blank" rel="noreferrer">Stripe Dashboard</a>.</li><li><strong>Turn off “Test mode”</strong> (toggle in the top right).</li><li>Go to <strong>Developers → API keys</strong>.</li><li>Copy: <ul><li><strong>Publishable key</strong> (<code>pk_live_...</code>)</li><li><strong>Secret key</strong> (<code>sk_live_...</code>) – keep this secret; use only in backend env.</li></ul></li></ol><h3 id="step-2-create-a-live-webhook-endpoint" tabindex="-1">Step 2: Create a live webhook endpoint <a class="header-anchor" href="#step-2-create-a-live-webhook-endpoint" aria-label="Permalink to &quot;Step 2: Create a live webhook endpoint&quot;">​</a></h3><ol><li>In Stripe Dashboard (still in <strong>live</strong> mode), go to <strong>Developers → Webhooks</strong>.</li><li>Click <strong>Add endpoint</strong>.</li><li><strong>Endpoint URL:</strong> your live backend URL + <code>/webhooks/stripe</code><br> Example: <code>https://your-backend.onrender.com/webhooks/stripe</code><br> (Use the real URL Render gives your server.)</li><li><strong>Events to send:</strong> either “Select events” and add at least: <ul><li><code>checkout.session.completed</code></li><li><code>payment_intent.succeeded</code></li><li><code>account.updated</code></li><li><code>account.application.deauthorized</code></li><li><code>charge.dispute.created</code></li><li><code>charge.dispute.closed</code></li><li><code>payout.failed</code></li><li><code>payout.paid</code><br> Or choose “Receive all events” if you prefer.</li></ul></li><li>Create the endpoint. Stripe will show <strong>Signing secret</strong> (<code>whsec_...</code>). Copy it.</li></ol><h3 id="step-3-set-environment-variables-on-render" tabindex="-1">Step 3: Set environment variables on Render <a class="header-anchor" href="#step-3-set-environment-variables-on-render" aria-label="Permalink to &quot;Step 3: Set environment variables on Render&quot;">​</a></h3><p>In Render, set these for your <strong>backend</strong> service (e.g. Node server):</p><ul><li><code>STRIPE_SECRET_KEY</code> = <code>sk_live_...</code> (from Step 1)</li><li><code>STRIPE_WEBHOOK_SECRET</code> = <code>whsec_...</code> (from Step 2 – <strong>the one for the live endpoint</strong>, not from Stripe CLI)</li></ul><p>Also set any other env vars your app needs (e.g. <code>Frontend_URL</code> / <code>FRONTEND_URL</code> to your live frontend URL for Stripe redirects).</p><p>For your <strong>frontend</strong> (if it’s a separate service on Render):</p><ul><li><code>VITE_STRIPE_PUBLISHABLE_KEY</code> = <code>pk_live_...</code> (from Step 1)</li></ul><p>Redeploy after changing env vars so they take effect.</p><h3 id="step-4-frontend-url-for-stripe-redirects" tabindex="-1">Step 4: Frontend URL for Stripe redirects <a class="header-anchor" href="#step-4-frontend-url-for-stripe-redirects" aria-label="Permalink to &quot;Step 4: Frontend URL for Stripe redirects&quot;">​</a></h3><p>Your backend uses <code>FRONTEND_URL</code> (or <code>Frontend_URL</code>) when building Stripe Checkout success/cancel URLs and return URLs. On Render, set this to your <strong>live</strong> frontend URL (e.g. <code>https://your-app.onrender.com</code>) so after payment users are sent back to your live site.</p><hr><h2 id="_5-summary-table" tabindex="-1">5. Summary table <a class="header-anchor" href="#_5-summary-table" aria-label="Permalink to &quot;5. Summary table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Localhost (dev)</th><th>Render with <strong>test</strong> credentials</th><th>Render with <strong>live</strong> (real payments)</th></tr></thead><tbody><tr><td><code>STRIPE_SECRET_KEY</code></td><td><code>sk_test_...</code></td><td><code>sk_test_...</code></td><td><code>sk_live_...</code></td></tr><tr><td><code>STRIPE_WEBHOOK_SECRET</code></td><td>From <code>stripe listen</code> (CLI)</td><td>From <strong>Dashboard</strong> webhook (test mode) for <code>https://your-api.onrender.com/webhooks/stripe</code></td><td>From <strong>Dashboard</strong> webhook (live mode) for same URL</td></tr><tr><td><code>VITE_STRIPE_PUBLISHABLE_KEY</code> (frontend)</td><td><code>pk_test_...</code></td><td><code>pk_test_...</code></td><td><code>pk_live_...</code></td></tr><tr><td><code>FRONTEND_URL</code> (backend)</td><td><code>http://localhost:5173</code></td><td><code>https://your-app.onrender.com</code></td><td><code>https://your-app.onrender.com</code></td></tr></tbody></table><p><strong>Important:</strong> The CLI secret from <code>stripe listen</code> only works when the CLI is forwarding to localhost. On Render you must create a webhook endpoint in the Dashboard (test or live) for your Render URL and use that endpoint’s signing secret.</p><hr><h2 id="_6-important-points" tabindex="-1">6. Important points <a class="header-anchor" href="#_6-important-points" aria-label="Permalink to &quot;6. Important points&quot;">​</a></h2><ol><li><strong>Stripe CLI webhook secret</strong> is for <strong>localhost only</strong>. Do not use it as <code>STRIPE_WEBHOOK_SECRET</code> on Render.</li><li><strong>Test keys</strong> work on Render but only for test payments. For real payments use <strong>live</strong> keys and a <strong>live</strong> webhook endpoint.</li><li><strong>One webhook endpoint per URL.</strong> Your live endpoint has its own signing secret; that’s the one your live backend must use.</li><li>After changing keys or webhook secret, <strong>restart/redeploy</strong> the backend so it reads the new env.</li><li>Keep <strong>live</strong> secret keys and webhook secrets only in Render (or your host) env; never commit them to the repo.</li></ol><p>Once you switch to live keys and the live webhook endpoint on Render, real payments will work and webhooks will verify correctly.</p>',52)])])}const u=t(s,[["render",i]]);export{p as __pageData,u as default};
